inline void features(const float window[100][6], float out[32]) {
    for (size_t c = 0; c < 8; ++c) {
        double sum = 0.0, sum_squared = 0.0;
        float lo = INFINITY, hi = -INFINITY;
        for (size_t i = 0; i < 100; ++i) {
            float value;
            if (c < 6) value = window[i][c];
            else {
                size_t base = c == 6 ? 0 : 3;
                double squared = 0.0;
                for (size_t j = 0; j < 3; ++j) {
                    double x = window[i][base+j]; squared += x*x;
                }
                value = static_cast<float>(std::sqrt(squared));
            }
            sum += value; sum_squared += static_cast<double>(value)*value;
            if (value < lo) lo = value;
            if (value > hi) hi = value;
        }
        double mean = sum / 100.0;
        double variance = sum_squared / 100.0 - mean*mean;
        out[4*c] = static_cast<float>(mean);
        out[4*c+1] = static_cast<float>(std::sqrt(variance > 0.0 ? variance : 0.0));
        out[4*c+2] = lo; out[4*c+3] = hi;
    }
}
